use xiom.io;

use xiom.string;
fn count_frequencies(items: &Vec[Int]) -> Map[Int, Int] {
  let counts: Map[Int, Int] = Map[Int, Int].new();
  let i = 0;
  while i < items.len() {
    let item = match items.get(i) { Some(v) => v, None => 0 };
    let current = match counts.get(&item) { Some(c) => c, None => 0 };
    counts.insert(item, current + 1);
    i = i + 1;
  }
  return counts;
}

fn find_most_frequent(counts: &Map[Int, Int], items: &Vec[Int]) -> Int {
  let best = 0;
  let max = 0;
  let i = 0;
  while i < items.len() {
    let item = match items.get(i) { Some(v) => v, None => 0 };
    let count = match counts.get(&item) { Some(c) => c, None => 0 };
    if count > max {
      max = count;
      best = item;
    }
    i = i + 1;
  }
  return best;
}

fn main() -> Int {
  let numbers: Vec[Int] = Vec[Int].new();
  numbers.push(1); numbers.push(2); numbers.push(1); numbers.push(3); numbers.push(1);

  let counts = count_frequencies(&numbers);
  let most = find_most_frequent(&counts, &numbers);
  io.println(string.int_to_str(most));
  return 0;
}
